import { buttonBaseClasses } from '@mui/material/ButtonBase';
import { useDefaultProps } from '@mui/material/DefaultPropsProvider';
import type { SxProps, Theme } from '@mui/material/styles';
import Switch, {
  switchClasses,
  type SwitchOwnerState,
  type SwitchProps,
} from '@mui/material/Switch';
import { mergeSlotProps } from '@mui/material/utils';
import type { SystemStyleObject } from '@mui/system';
import clsx from 'clsx';
import { mergeSx } from 'merge-sx';
import { forwardRef, type Ref } from 'react';
import { svTokens } from '../../theme/tokens';

export interface SvSwitchProps extends Omit<SwitchProps, 'ref'> {
  ref?: Ref<HTMLSpanElement> | undefined;
}

declare module '@mui/material/styles' {
  interface ComponentsPropsList {
    SvSwitch: SvSwitchProps;
  }
  interface Components {
    SvSwitch?:
      { defaultProps?: Partial<SvSwitchProps> | undefined } | undefined;
  }
}

type Slots = NonNullable<SwitchProps['slotProps']>;
const checked = `&:has(> .${switchClasses.switchBase}.${switchClasses.checked})`;
const disabled = `&:has(> .${switchClasses.switchBase}.${switchClasses.disabled})`;

function switchBaseSx(theme: Theme): SystemStyleObject<Theme> {
  return {
    padding: '4px',
    color: 'var(--SvSwitch-thumb-color)',
    transform: 'translateX(var(--SvSwitch-offset))',
    '&:hover': {
      backgroundColor: `color-mix(in srgb, currentColor calc(${(theme.vars ?? theme).palette.action.hoverOpacity} * 100%), transparent)`,
      '@media (hover: none)': { backgroundColor: 'transparent' },
    },
    [`&.${buttonBaseClasses.focusVisible}`]: {
      outline: `2px solid ${svTokens(theme).focus}`,
      outlineOffset: 2,
      '@media (forced-colors: active)': { outlineColor: 'Highlight' },
    },
  };
}
const thumbSx: SxProps<Theme> = {
  width: 'var(--SvSwitch-thumb-size)',
  height: 'var(--SvSwitch-thumb-size)',
  boxShadow: 'none',
  backgroundColor: 'currentColor',
};
const trackSx: SxProps<Theme> = {
  borderRadius: '14px',
  backgroundColor: 'var(--SvSwitch-track-color)',
  opacity: 'var(--SvSwitch-track-opacity)',
};

export const SvSwitch = forwardRef<HTMLSpanElement, SvSwitchProps>(
  function SvSwitch(inProps, ref) {
    const muiDefaults = useDefaultProps<SvSwitchProps>({
      props: {},
      name: 'MuiSwitch',
    });
    const svDefaults = useDefaultProps<SvSwitchProps>({
      props: {},
      name: 'SvSwitch',
    });
    const svProps = useDefaultProps({ props: inProps, name: 'SvSwitch' });
    const resolved = useDefaultProps({ props: svProps, name: 'MuiSwitch' });
    const {
      className,
      sx: _sx,
      slotProps: _slotProps,
      size = 'medium',
      color = 'primary',
      ...props
    } = resolved;
    const controlSx: SxProps<Theme> = (theme) => {
      const palette = (theme.vars ?? theme).palette;
      const swatch = palette[color as keyof typeof palette];
      const fill =
        color === 'primary'
          ? svTokens(theme).green
          : swatch && typeof swatch === 'object' && 'main' in swatch
            ? (swatch.main as string)
            : palette.text.secondary;
      return {
        width: size === 'small' ? 40 : 42,
        height: size === 'small' ? 24 : 28,
        padding: size === 'small' ? '7px' : '7px 4px',
        overflow: 'visible',
        '--SvSwitch-neutral': palette.text.secondary,
        '--SvSwitch-selected': fill,
        '--SvSwitch-thumb-size': size === 'small' ? '16px' : '20px',
        '--SvSwitch-thumb-color': 'var(--SvSwitch-neutral)',
        '--SvSwitch-track-color': 'var(--SvSwitch-neutral)',
        '--SvSwitch-track-opacity': 0.32,
        '--SvSwitch-offset': '0px',
        [checked]: {
          '--SvSwitch-offset': size === 'small' ? '16px' : '14px',
          '--SvSwitch-thumb-color': 'var(--SvSwitch-selected)',
          '--SvSwitch-track-color': 'var(--SvSwitch-selected)',
          '--SvSwitch-track-opacity': 0.6,
        },
        [disabled]: {
          opacity: 0.5,
          '--SvSwitch-thumb-color': 'var(--SvSwitch-neutral)',
          '--SvSwitch-track-color': 'var(--SvSwitch-neutral)',
          '--SvSwitch-track-opacity': 0.32,
        },
        '@media (prefers-reduced-motion: reduce)': {
          '&& *, && *::before, && *::after': {
            transition: 'none',
            animation: 'none',
          },
        },
        '@media (forced-colors: active)': {
          forcedColorAdjust: 'none',
          '--SvSwitch-neutral': 'CanvasText',
          '--SvSwitch-selected': 'Highlight',
          '--SvSwitch-track-opacity': 1,
          [checked]: { '--SvSwitch-track-opacity': 1 },
          [disabled]: {
            opacity: 1,
            '--SvSwitch-neutral': 'GrayText',
            '--SvSwitch-track-opacity': 1,
          },
        },
      };
    };
    const slot = <K extends keyof Slots>(name: K): NonNullable<Slots[K]> => {
      return mergeSlotProps(
        inProps.slotProps?.[name],
        mergeSlotProps(
          svDefaults.slotProps?.[name],
          muiDefaults.slotProps?.[name] ?? {}
        )
      ) as NonNullable<Slots[K]>;
    };
    const styledSlot = <K extends 'switchBase' | 'thumb' | 'track'>(
      name: K,
      sx: SxProps<Theme>
    ): NonNullable<Slots[K]> => {
      const merged = mergeSlotProps(slot(name), { sx }) as
        | { sx?: SxProps<Theme> }
        | ((ownerState: SwitchOwnerState) => { sx?: SxProps<Theme> });
      return ((ownerState: SwitchOwnerState) => {
        const value =
          typeof merged === 'function' ? merged(ownerState) : merged;
        return {
          ...value,
          // MUI's state/size rules otherwise override the inner slot styles.
          // Lift the entire merged sx so consumer overrides keep the same priority.
          sx: (theme: Theme) => ({ '&&&&': theme.unstable_sx(value.sx ?? {}) }),
        };
      }) as NonNullable<Slots[K]>;
    };
    const rootSx = mergeSx(
      controlSx,
      muiDefaults.sx,
      svDefaults.sx,
      inProps.sx
    );
    return (
      <Switch
        {...props}
        size={size}
        color={color}
        // MUI 9.4 forwards this ref to SwitchBase's span, despite its button type.
        ref={ref as Ref<HTMLButtonElement>}
        className={clsx('SvSwitch-root', className)}
        sx={rootSx}
        slotProps={{
          root: mergeSlotProps(slot('root'), { sx: rootSx }),
          switchBase: styledSlot('switchBase', switchBaseSx),
          thumb: styledSlot('thumb', thumbSx),
          track: styledSlot('track', trackSx),
          input: slot('input'),
        }}
      />
    );
  }
);
